const $=s=>document.querySelector(s);let doc=null,saved='',previewRevision=null;
const editor=new PatchEditor($('#editor'),$('#editorShell'),$('#spacer'),()=>{updateSaved();clearMessage()});
function message(text,success=false){$('#message').textContent=text;$('#message').className=success?'success':''}function clearMessage(){if(!$('#message').classList.contains('sticky'))message('')}
function updateSaved(){const dirty=doc&&editor.text!==saved;$('#saveState').textContent=dirty?'Unsaved changes':'Saved';$('#saveState').className=dirty?'dirty':'';$('#save').disabled=!doc||!dirty}
