async function preview(rev){try{const r=await request(`/api/documents/${encodeURIComponent(doc.id)}/revisions/${rev}`);previewRevision=rev;$('#previewTitle').textContent=`Revision ${rev} preview`;$('#previewDate').textContent=new Date(r.createdAt).toLocaleString();$('#previewContent').textContent=r.content;$('#restoreRevision').disabled=rev===doc.revision;$('#previewDialog').showModal()}catch(e){message(e.message)}}
