$('#save').onclick=save;$('#undo').onclick=()=>editor.undo();$('#redo').onclick=()=>editor.redo();$('#findNext').onclick=findNext;$('#replaceCurrent').onclick=replaceCurrent;$('#replaceAll').onclick=replaceAll;$('#find').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();findNext()}});$('#closePreview').onclick=()=>$('#previewDialog').close();$('#restoreRevision').onclick=restore;window.addEventListener('beforeunload',e=>{if(doc&&editor.text!==saved){e.preventDefault();e.returnValue=''}});load();
