:root{color-scheme:dark;--bg:#10141b;--panel:#171d27;--line:#2b3442;--muted:#94a3b8;--text:#e5edf6;--accent:#67e8c5;--danger:#fca5a5;--select:#254d6f}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,sans-serif}header{height:74px;padding:12px 22px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:38px;background:#131923}.brand{font-size:21px;color:var(--accent)}.tagline{display:block;color:var(--muted);font-size:12px}.document-heading h1{font-size:17px;margin:0 0 4px}.document-heading span{color:var(--muted);font-size:12px}main{padding:12px 18px}.toolbar{display:flex;align-items:end;gap:7px;flex-wrap:wrap}.toolbar label{display:flex;flex-direction:column;color:var(--muted);font-size:11px;gap:3px}.divider{height:30px;border-left:1px solid var(--line);margin:0 4px}button,input{border:1px solid #3a4658;background:#202938;color:var(--text);border-radius:5px;padding:7px 10px}button{cursor:pointer}button:hover:not(:disabled){border-color:var(--accent)}button:disabled{opacity:.45;cursor:not-allowed}.primary{background:#0d6d5a;border-color:#1aa98a;font-weight:700}input{width:145px}#message{min-height:28px;padding:7px 2px;color:var(--danger)}#message.success{color:var(--accent)}.workspace{display:grid;grid-template-columns:minmax(500px,1fr) 260px;gap:12px;height:calc(100vh - 157px);min-height:380px}.editor-panel,aside{background:var(--panel);border:1px solid var(--line);border-radius:7px;min-height:0}#editorShell{height:calc(100% - 34px);overflow:auto;position:relative;background:#111721;cursor:text;scrollbar-color:#435064 #151b25}#editor{position:sticky;z-index:2;top:0;left:0;display:block;outline:none;background:#111721}#editor:focus{box-shadow:inset 0 0 0 1px #2d8875}#spacer{position:absolute;z-index:1;top:0;left:0;pointer-events:none}.statusbar{height:34px;border-top:1px solid var(--line);display:flex;align-items:center;gap:20px;padding:0 12px;color:var(--muted);font-size:12px}.statusbar #saveState{margin-left:auto;color:var(--accent)}.statusbar #saveState.dirty{color:#fbbf24}aside{padding:13px;overflow:auto}aside h2{font-size:14px;margin:0}.hint{color:var(--muted);font-size:12px}.revision-item{display:grid;grid-template-columns:1fr auto;gap:3px;border-top:1px solid var(--line);padding:9px 0}.revision-item small{color:var(--muted);grid-column:1}.revision-item button{grid-row:1/3;grid-column:2;padding:5px 8px}dialog{width:min(850px,90vw);height:80vh;background:var(--panel);border:1px solid #49566a;color:var(--text);border-radius:8px;padding:0}dialog::backdrop{background:#000a}.dialog-head{display:flex;justify-content:space-between;align-items:center;padding:14px;border-bottom:1px solid var(--line)}.dialog-head h2,.dialog-head p{margin:0 0 3px}.dialog-head p{color:var(--muted)}#previewContent{margin:0;padding:16px;height:calc(100% - 125px);overflow:auto;white-space:pre;font:13px/1.5 ui-monospace,monospace}.dialog-actions{border-top:1px solid var(--line);padding:10px;text-align:right}@media(max-width:800px){.workspace{grid-template-columns:1fr;grid-template-rows:minmax(400px,1fr) 180px;height:auto}.editor-panel{height:65vh}header{gap:15px}.tagline{display:none}}
