'use strict';

class PatchEditor {
  constructor(canvas, shell, spacer, onChange) {
    this.canvas=canvas; this.ctx=canvas.getContext('2d'); this.shell=shell; this.spacer=spacer; this.onChange=onChange;
    this.text=''; this.lines=['']; this.starts=[0]; this.ranges=[{anchor:0,head:0}]; this.undoStack=[]; this.redoStack=[];
    this.lineHeight=21; this.charWidth=8.4; this.gutter=66; this.pad=10; this.dragging=false; this.goalColumn=null; this.blink=true;
    this.bind(); new ResizeObserver(()=>this.resize()).observe(shell); setInterval(()=>{this.blink=!this.blink;this.draw()},530);
  }
  bind(){
    this.canvas.addEventListener('keydown',e=>this.keydown(e));
    this.canvas.addEventListener('copy',e=>this.copy(e)); this.canvas.addEventListener('cut',e=>this.cut(e)); this.canvas.addEventListener('paste',e=>this.paste(e));
    this.canvas.addEventListener('pointerdown',e=>this.pointerDown(e)); this.canvas.addEventListener('pointermove',e=>this.pointerMove(e));
    this.canvas.addEventListener('pointerup',()=>{this.dragging=false}); this.canvas.addEventListener('pointercancel',()=>{this.dragging=false});
    this.shell.addEventListener('scroll',()=>this.draw());
  }
  setText(text, reset=true){this.text=text;this.reindex();if(reset){this.ranges=[{anchor:0,head:0}];this.undoStack=[];this.redoStack=[]}this.measure();this.draw();this.status()}
  reindex(){this.lines=this.text.split('\n');this.starts=[];let p=0;for(const line of this.lines){this.starts.push(p);p+=line.length+1}}
  resize(){const d=devicePixelRatio||1,w=this.shell.clientWidth,h=this.shell.clientHeight;if(w<1||h<1)return;this.canvas.style.width=w+'px';this.canvas.style.height=h+'px';this.canvas.width=Math.floor(w*d);this.canvas.height=Math.floor(h*d);this.ctx.setTransform(d,0,0,d,0,0);this.measure();this.draw()}
  measure(){const max=Math.max(1,...this.lines.map(l=>l.length));this.spacer.style.width=Math.max(this.shell.clientWidth,this.gutter+this.pad*2+max*this.charWidth)+'px';this.spacer.style.height=Math.max(this.shell.clientHeight,this.lines.length*this.lineHeight+this.pad*2)+'px'}
  lineCol(pos){pos=Math.max(0,Math.min(this.text.length,pos));let lo=0,hi=this.starts.length-1;while(lo<=hi){const m=(lo+hi)>>1;if(this.starts[m]<=pos)lo=m+1;else hi=m-1}const line=Math.max(0,hi);return {line,col:Math.min(pos-this.starts[line],this.lines[line].length)}}
  position(line,col){line=Math.max(0,Math.min(this.lines.length-1,line));return this.starts[line]+Math.max(0,Math.min(this.lines[line].length,col))}
  eventPosition(e){const rect=this.canvas.getBoundingClientRect();const x=e.clientX-rect.left+this.shell.scrollLeft;const y=e.clientY-rect.top+this.shell.scrollTop;return this.position(Math.floor((y-this.pad)/this.lineHeight),Math.round((x-this.gutter-this.pad)/this.charWidth))}
  norm(r){return [Math.min(r.anchor,r.head),Math.max(r.anchor,r.head)]}
  selectedText(){return this.ranges.map(r=>{const[a,b]=this.norm(r);return this.text.slice(a,b)}).filter(Boolean).join('\n')}
  snapshot(){return {text:this.text,ranges:this.ranges.map(r=>({...r}))}}
  restore(s){this.text=s.text;this.ranges=s.ranges.map(r=>({...r}));this.reindex();this.measure();this.draw();this.status();this.onChange()}
  edit(insert,kind='edit'){
    const before=this.snapshot();let ops=this.ranges.map((r,i)=>{let[a,b]=this.norm(r);if(kind==='backspace'&&a===b&&a>0)a--;if(kind==='delete'&&a===b&&b<this.text.length)b++;return{a,b,i}}).sort((x,y)=>y.a-x.a||y.b-x.b);
    const dedup=[];for(const op of ops)if(!dedup.some(x=>op.a<=x.b&&op.b>=x.a))dedup.push(op);
    let text=this.text;const carets=[];for(const op of dedup){text=text.slice(0,op.a)+insert+text.slice(op.b);carets.push({base:op.a+insert.length,op})}
    if(text===this.text)return;this.undoStack.push(before);if(this.undoStack.length>200)this.undoStack.shift();this.redoStack=[];this.text=text;
    this.ranges=carets.map(c=>{let shift=0;for(const other of dedup)if(other.a<c.op.a)shift+=insert.length-(other.b-other.a);const p=c.base+shift;return{anchor:p,head:p}}).sort((a,b)=>a.head-b.head);
    this.reindex();this.measure();this.ensureVisible();this.draw();this.status();this.onChange();
  }
  undo(){if(!this.undoStack.length)return;this.redoStack.push(this.snapshot());this.restore(this.undoStack.pop())}
  redo(){if(!this.redoStack.length)return;this.undoStack.push(this.snapshot());this.restore(this.redoStack.pop())}
  move(key,extend,word=false){
    this.ranges=this.ranges.map(r=>{let p=r.head;const lc=this.lineCol(p);if(!extend&&r.anchor!==r.head){const[a,b]=this.norm(r);p=(key==='ArrowLeft'||key==='ArrowUp'||key==='Home')?a:b}else if(key==='ArrowLeft')p=word?this.wordLeft(p):Math.max(0,p-1);else if(key==='ArrowRight')p=word?this.wordRight(p):Math.min(this.text.length,p+1);else if(key==='Home')p=this.starts[lc.line];else if(key==='End')p=this.starts[lc.line]+this.lines[lc.line].length;else{const delta=key==='ArrowUp'?-1:1;const col=this.goalColumn??lc.col;p=this.position(lc.line+delta,col)}return{anchor:extend?r.anchor:p,head:p}});
    if(key==='ArrowUp'||key==='ArrowDown')this.goalColumn=this.goalColumn??this.lineCol(this.ranges[0].head).col;else this.goalColumn=null;this.ensureVisible();this.draw();this.status();
  }
  wordLeft(p){while(p>0&&/\s/.test(this.text[p-1]))p--;while(p>0&&/[\w-]/.test(this.text[p-1]))p--;return p}
  wordRight(p){while(p<this.text.length&&/[\w-]/.test(this.text[p]))p++;while(p<this.text.length&&/\s/.test(this.text[p]))p++;return p}
  keydown(e){const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?this.redo():this.undo();return}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();this.redo();return}if(mod&&e.key.toLowerCase()==='a'){e.preventDefault();this.ranges=[{anchor:0,head:this.text.length}];this.draw();this.status();return}if(mod&&['c','x','v'].includes(e.key.toLowerCase()))return;
    if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();this.move(e.key,e.shiftKey,mod);return}if(e.key==='Backspace'||e.key==='Delete'){e.preventDefault();this.edit('',e.key.toLowerCase());return}if(e.key==='Enter'){e.preventDefault();this.edit('\n');return}if(e.key==='Tab'){e.preventDefault();this.edit('  ');return}if(!mod&&!e.altKey&&e.key.length===1){e.preventDefault();this.edit(e.key)}
  }
  copy(e){const t=this.selectedText();if(t){e.preventDefault();e.clipboardData.setData('text/plain',t)}}
  cut(e){const t=this.selectedText();if(t){e.preventDefault();e.clipboardData.setData('text/plain',t);this.edit('')}}
  paste(e){e.preventDefault();this.edit(e.clipboardData.getData('text/plain').replace(/\r\n?/g,'\n'))}
  pointerDown(e){e.preventDefault();this.canvas.focus();const p=this.eventPosition(e);if(e.detail>=3){const lc=this.lineCol(p),a=this.starts[lc.line],b=a+this.lines[lc.line].length+(lc.line<this.lines.length-1?1:0);this.ranges=[{anchor:a,head:b}]}else if(e.detail===2){let a=p,b=p;while(a>0&&/[\w-]/.test(this.text[a-1]))a--;while(b<this.text.length&&/[\w-]/.test(this.text[b]))b++;this.ranges=[{anchor:a,head:b}]}else if(e.altKey||e.ctrlKey||e.metaKey){this.ranges.push({anchor:p,head:p})}else if(e.shiftKey){this.ranges=[{anchor:this.ranges[0].anchor,head:p}]}else this.ranges=[{anchor:p,head:p}];this.dragging=true;this.canvas.setPointerCapture(e.pointerId);this.draw();this.status()}
  pointerMove(e){if(!this.dragging)return;const rect=this.canvas.getBoundingClientRect();if(e.clientY<rect.top+20)this.shell.scrollTop-=this.lineHeight*2;if(e.clientY>rect.bottom-20)this.shell.scrollTop+=this.lineHeight*2;if(e.clientX<rect.left+this.gutter)this.shell.scrollLeft-=30;if(e.clientX>rect.right-20)this.shell.scrollLeft+=30;this.ranges[this.ranges.length-1].head=this.eventPosition(e);this.ensureVisible(false);this.draw();this.status()}
  ensureVisible(scroll=true){const lc=this.lineCol(this.ranges.at(-1).head),x=this.gutter+this.pad+lc.col*this.charWidth,y=this.pad+lc.line*this.lineHeight;if(scroll){if(y<this.shell.scrollTop)this.shell.scrollTop=y;if(y+this.lineHeight>this.shell.scrollTop+this.shell.clientHeight)this.shell.scrollTop=y-this.shell.clientHeight+this.lineHeight;if(x<this.shell.scrollLeft+this.gutter)this.shell.scrollLeft=Math.max(0,x-this.gutter);if(x>this.shell.scrollLeft+this.shell.clientWidth-20)this.shell.scrollLeft=x-this.shell.clientWidth+20}}
  status(){const lc=this.lineCol(this.ranges[0].head);document.querySelector('#cursor').textContent=`Line ${lc.line+1}, Column ${lc.col+1}`;document.querySelector('#carets').textContent=`${this.ranges.length} caret${this.ranges.length===1?'':'s'}`;document.querySelector('#undo').disabled=!this.undoStack.length;document.querySelector('#redo').disabled=!this.redoStack.length}
  draw(){const c=this.ctx,w=this.shell.clientWidth,h=this.shell.clientHeight,top=this.shell.scrollTop,left=this.shell.scrollLeft;c.clearRect(0,0,w,h);c.fillStyle='#111721';c.fillRect(0,0,w,h);c.font='14px ui-monospace, SFMono-Regular, Menlo, monospace';c.textBaseline='top';const first=Math.max(0,Math.floor((top-this.pad)/this.lineHeight)),last=Math.min(this.lines.length,Math.ceil((top+h)/this.lineHeight)+1);
    c.fillStyle='#171f2b';c.fillRect(0,0,this.gutter,h);c.strokeStyle='#2b3442';c.beginPath();c.moveTo(this.gutter-.5,0);c.lineTo(this.gutter-.5,h);c.stroke();
    for(let i=first;i<last;i++){const y=this.pad+i*this.lineHeight-top;c.fillStyle='#718096';c.textAlign='right';c.fillText(String(i+1),this.gutter-10,y);c.textAlign='left';for(const r of this.ranges){const[a,b]=this.norm(r),ls=this.starts[i],le=ls+this.lines[i].length;if(b>ls&&a<=le){const x1=this.gutter+this.pad+(Math.max(a,ls)-ls)*this.charWidth-left,x2=this.gutter+this.pad+(Math.min(b,le)-ls)*this.charWidth-left;c.fillStyle='#254d6f';c.fillRect(x1,y,Math.max(this.charWidth,x2-x1),this.lineHeight)}}c.fillStyle='#dce6f2';c.fillText(this.lines[i],this.gutter+this.pad-left,y)}
    if(document.activeElement===this.canvas&&this.blink)for(const r of this.ranges){const lc=this.lineCol(r.head);if(lc.line>=first&&lc.line<last){const x=this.gutter+this.pad+lc.col*this.charWidth-left,y=this.pad+lc.line*this.lineHeight-top;c.fillStyle='#67e8c5';c.fillRect(x,y,2,this.lineHeight)}}
  }
}

const $=s=>document.querySelector(s);let doc=null,saved='',previewRevision=null;
const editor=new PatchEditor($('#editor'),$('#editorShell'),$('#spacer'),()=>{updateSaved();clearMessage()});
function message(text,success=false){$('#message').textContent=text;$('#message').className=success?'success':''}function clearMessage(){if(!$('#message').classList.contains('sticky'))message('')}
function updateSaved(){const dirty=doc&&editor.text!==saved;$('#saveState').textContent=dirty?'Unsaved changes':'Saved';$('#saveState').className=dirty?'dirty':'';$('#save').disabled=!doc||!dirty}
async function request(url,options){const r=await fetch(url,options);const body=await r.json();if(!r.ok)throw Object.assign(new Error(body.error||'Request failed.'),{status:r.status,body});return body}
async function load(){try{const docs=await request('/api/documents');if(!docs.length)throw new Error('No documents are available.');doc=await request(`/api/documents/${encodeURIComponent(docs[0].id)}`);saved=doc.content;editor.setText(saved);$('#title').textContent=doc.title;$('#author').textContent=`By ${doc.author} · ${doc.summary}`;revisionStatus();updateSaved();await history()}catch(e){message(e.message)}}
function revisionStatus(){$('#revision').textContent=`Revision ${doc.revision}`}
async function save(){try{const result=await request(`/api/documents/${encodeURIComponent(doc.id)}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:doc.id,baseRevision:doc.revision,content:editor.text})});doc=result.document;saved=doc.content;revisionStatus();updateSaved();message(result.unchanged?'Already saved; no new revision created.':`Saved revision ${doc.revision}.`,true);await history()}catch(e){message(e.status===409?`${e.message} Reload to see the newer saved content; your edits remain here.`:e.message)}}
async function history(){try{const rows=await request(`/api/documents/${encodeURIComponent(doc.id)}/revisions`);$('#history').replaceChildren(...rows.map(r=>{const item=document.createElement('div');item.className='revision-item';const strong=document.createElement('strong');strong.textContent=`Revision ${r.revision}${r.revision===doc.revision?' (current)':''}`;const small=document.createElement('small');small.textContent=new Date(r.createdAt).toLocaleString();const btn=document.createElement('button');btn.textContent='Preview';btn.onclick=()=>preview(r.revision);item.append(strong,small,btn);return item}))}catch(e){message(e.message)}}
async function preview(rev){try{const r=await request(`/api/documents/${encodeURIComponent(doc.id)}/revisions/${rev}`);previewRevision=rev;$('#previewTitle').textContent=`Revision ${rev} preview`;$('#previewDate').textContent=new Date(r.createdAt).toLocaleString();$('#previewContent').textContent=r.content;$('#restoreRevision').disabled=rev===doc.revision;$('#previewDialog').showModal()}catch(e){message(e.message)}}
async function restore(){if(previewRevision===null)return;try{const result=await request(`/api/documents/${encodeURIComponent(doc.id)}/restore/${previewRevision}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:doc.id,baseRevision:doc.revision})});doc=result.document;saved=doc.content;editor.setText(saved);revisionStatus();updateSaved();$('#previewDialog').close();message(`Restored revision ${previewRevision} as new revision ${doc.revision}.`,true);await history()}catch(e){message(e.message)}}
function matches(){const q=$('#find').value;if(!q)return[];const out=[];let p=0;while((p=editor.text.indexOf(q,p))!==-1){out.push([p,p+q.length]);p+=Math.max(1,q.length)}return out}
function findNext(){const all=matches();if(!all.length)return message('No matches found.');const p=editor.ranges[0].head;const hit=all.find(x=>x[0]>=p&&!(editor.ranges[0].anchor===x[0]&&editor.ranges[0].head===x[1]))||all[0];editor.ranges=[{anchor:hit[0],head:hit[1]}];editor.ensureVisible();editor.draw();editor.status();message(`${all.indexOf(hit)+1} of ${all.length} matches.`,true)}
function replaceCurrent(){const q=$('#find').value;if(!q)return message('Enter text to find.');const[a,b]=editor.norm(editor.ranges[0]);if(editor.text.slice(a,b)!==q)findNext();const[c,d]=editor.norm(editor.ranges[0]);if(editor.text.slice(c,d)===q)editor.edit($('#replace').value)}
function replaceAll(){const all=matches();if(!all.length)return message('No matches found.');editor.ranges=all.map(([a,b])=>({anchor:a,head:b}));editor.edit($('#replace').value);message(`Replaced ${all.length} matches.`,true)}
$('#save').onclick=save;$('#undo').onclick=()=>editor.undo();$('#redo').onclick=()=>editor.redo();$('#findNext').onclick=findNext;$('#replaceCurrent').onclick=replaceCurrent;$('#replaceAll').onclick=replaceAll;$('#find').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();findNext()}});$('#closePreview').onclick=()=>$('#previewDialog').close();$('#restoreRevision').onclick=restore;window.addEventListener('beforeunload',e=>{if(doc&&editor.text!==saved){e.preventDefault();e.returnValue=''}});load();
